import {STAGES} from '../data.js?v=1.7.17';
import {loadSave} from '../store.js?v=1.7.17';
import {MAP_STAGE_IDS,regionAccess,unlockedStage} from '../stage-access.js?v=1.7.17';
let save=loadSave();
const data=await (await fetch('./hub/map-regions.json')).json();
const svg=document.querySelector('#map'),regionsNode=document.querySelector('#regions'),markersNode=document.querySelector('#markers'),back=document.querySelector('#back'),mapTitle=document.querySelector('#map-title'),help=document.querySelector('#map-help'),popup=document.querySelector('#mission-popup'),popupContent=document.querySelector('#popup-content');
const ns='http://www.w3.org/2000/svg',el=(name,attrs={})=>{const node=document.createElementNS(ns,name);for(const [key,value]of Object.entries(attrs))node.setAttribute(key,String(value));return node;};
const makePoints=points=>points.map(p=>p.join(',')).join(' ');
function inside([x,y],points){let yes=false;for(let i=0,j=points.length-1;i<points.length;j=i++){const [xi,yi]=points[i],[xj,yj]=points[j];if((yi>y)!==(yj>y)&&x<(xj-xi)*(y-yi)/(yj-yi)+xi)yes=!yes;}return yes;}
function layoutRegion(region){const p=region.polygon,minX=Math.max(0,Math.min(...p.map(x=>x[0]))),maxX=Math.min(904,Math.max(...p.map(x=>x[0]))),minY=Math.max(0,Math.min(...p.map(x=>x[1]))),maxY=Math.min(1204,Math.max(...p.map(x=>x[1]))),w=maxX-minX,h=maxY-minY;const center=[(minX+maxX)/2,(minY+maxY)/2];let candidates=[];for(let y=minY+h*.18;y<maxY-h*.12;y+=Math.max(6,h/16))for(let x=minX+w*.1;x<maxX-w*.1;x+=Math.max(6,w/16))if(inside([x,y],p))candidates.push([x,y]);if(!candidates.length)candidates=[center];candidates.sort((a,b)=>Math.hypot(a[0]-center[0],a[1]-center[1])-Math.hypot(b[0]-center[0],b[1]-center[1]));const label=candidates[0];let m1=candidates.find(q=>q[0]<label[0]-w*.12)||candidates[Math.floor(candidates.length*.2)]||label;let m2=candidates.find(q=>q[0]>label[0]+w*.12&&Math.hypot(q[0]-m1[0],q[1]-m1[1])>w*.18)||candidates.at(-1);return {minX,maxX,minY,maxY,w,h,label,markers:[m1,m2]};}
for(const r of data){r.layout=layoutRegion(r);
  if(r.name==='브릿지')r.layout.markers=[[436.4,770.4],[402.9,758.4]];
  if(r.name==='미지의 해안')r.layout.markers=[[305.6,796.5],[248.6,863.2]];
  if(r.name==='뉴 헤랜드')r.layout.markers=[[593.7,659.2],[591.4,701.2],[702.6,661.2],[628,595.6]];
  if(r.name==='미구엘')r.layout.markers=[[652.9,547.6],[672.2,492.2],[567.4,483.1],[659.8,458.2],[538.4,507.2]];
  r.stages=(MAP_STAGE_IDS[r.name]||[]).map(id=>STAGES.find(stage=>stage.id===id)).filter(Boolean);
}
let current=null,chosen=null,animation=0,view=[0,0,904,1204];const original=[...view];
function setView(values){view=values;svg.setAttribute('viewBox',values.map(n=>n.toFixed(2)).join(' '));}
function animateView(to){cancelAnimationFrame(animation);const from=[...view],start=performance.now(),duration=550;function step(now){const q=Math.min(1,(now-start)/duration),v=1-(1-q)**3;setView(from.map((x,i)=>x+(to[i]-x)*v));if(q<1)animation=requestAnimationFrame(step);}animation=requestAnimationFrame(step);}
function zoomBounds(region){const r=region.layout,ratio=svg.clientWidth/svg.clientHeight;let w=r.w*1.55,h=r.h*1.55;w=Math.max(w,150);h=Math.max(h,200);if(w/h<ratio)w=h*ratio;else h=w/ratio;w=Math.min(w,904);h=Math.min(h,1204);const x=Math.min(904-w,Math.max(0,(r.minX+r.maxX)/2-w/2)),y=Math.min(1204-h,Math.max(0,(r.minY+r.maxY)/2-h/2));return [x,y,w,h];}
function syncHover(index,active){document.querySelectorAll(`[data-region="${index}"]`).forEach(e=>e.classList.toggle('hovered',active));}
function drawRegions(){regionsNode.replaceChildren();data.forEach((r,i)=>{
  const access=regionAccess(r.name,save.maxStage),locked=access!=='open';
  const poly=el('polygon',{points:makePoints(r.polygon),class:'region'+(locked?' locked':'')+(current===i?' selected':current!==null?' dimmed':''),tabindex:current===null&&!locked?0:-1,role:'button','aria-disabled':locked?'true':'false','aria-label':locked?`${r.name} · ${access==='unavailable'?'추가 예정':'이전 스테이지 클리어 필요'}`:`${r.name} 구역 선택`,'data-region':i});
  poly.addEventListener('click',()=>selectRegion(i));poly.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectRegion(i);}});
  for(const [event,on]of [['mouseenter',true],['mouseleave',false],['focus',true],['blur',false]])poly.addEventListener(event,()=>syncHover(i,on));regionsNode.append(poly);
  const label=el('text',{x:r.layout.label[0],y:r.layout.label[1],class:'region-label'+(locked?' locked-label':'')+(current!==null?' hidden':'')});label.textContent=r.name;regionsNode.append(label);
});}
function stageDetails(stage){return `<button class="popup-close" aria-label="닫기">×</button><span class="danger">${stage.difficulty}</span><h2 id="popup-title">${stage.name}</h2><p>${stage.desc}</p><a class="launch" href="./?stage=${stage.id}">작전실 가기 →</a>`;}
let popupAnchor=null;
function positionPopup(){if(!popup.open||!popupAnchor)return;const pad=12,gap=14,box=popup.getBoundingClientRect(),w=window.innerWidth,h=window.innerHeight;let x=popupAnchor.x+gap,y=popupAnchor.y+gap;if(x+box.width>w-pad)x=popupAnchor.x-box.width-gap;if(y+box.height>h-pad)y=popupAnchor.y-box.height-gap;popup.style.left=Math.max(pad,Math.min(x,w-box.width-pad))+'px';popup.style.top=Math.max(pad,Math.min(y,h-box.height-pad))+'px';}
window.addEventListener('resize',positionPopup);
function chooseStage(index,event){const stage=data[current]?.stages[index];if(!stage||!unlockedStage(stage.id,STAGES,save.maxStage))return;chosen=index;const target=event?.currentTarget?.getBoundingClientRect();popupAnchor=event?.type==='click'&&event.detail!==0?{x:event.clientX,y:event.clientY}:{x:target?target.left+target.width/2:window.innerWidth/2,y:target?target.top+target.height/2:window.innerHeight/2};popupContent.innerHTML=stageDetails(stage);popupContent.querySelector('.popup-close').addEventListener('click',()=>popup.close());document.querySelectorAll('.marker').forEach((node,i)=>node.setAttribute('aria-pressed',String(i===index)));if(!popup.open)popup.showModal();positionPopup();}
function drawMarkers(){markersNode.replaceChildren();if(current===null)return;const region=data[current];region.stages.forEach((stage,i)=>{const [x,y]=region.layout.markers[i],locked=!unlockedStage(stage.id,STAGES,save.maxStage);const marker=el('g',{class:'marker'+(locked?' locked-marker':''),tabindex:locked?-1:0,role:'button','aria-disabled':String(locked),'aria-label':`${stage.name}${locked?' · 이전 스테이지 클리어 필요':' 임무 상세 보기'}`,'aria-pressed':String(chosen===i)});marker.append(el('circle',{cx:x,cy:y,r:5}));const toRight=region.name==='브릿지'?i===0:region.name==='뉴 헤랜드'?i>=2:region.name==='미구엘'?i===0||i===1||i===3:i!==0;const text=el('text',{x:x+(toRight?9:-9),y:y+(i%2?13:-8),'text-anchor':toRight?'start':'end'});text.textContent=`${String(stage.id).padStart(2,'0')} ${stage.name}`;marker.append(text);marker.addEventListener('click',e=>chooseStage(i,e));marker.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();chooseStage(i,e);}});markersNode.append(marker);const bounds=marker.getBBox();marker.insertBefore(el('rect',{class:'marker-hit',x:bounds.x-4,y:bounds.y-4,width:bounds.width+8,height:bounds.height+8,rx:3,'aria-hidden':'true'}),marker.firstChild);});}
function showDirectory(){mapTitle.textContent='전체 지도';help.textContent='열린 구역을 선택하세요';back.hidden=true;}
function selectRegion(i){const r=data[i];if(!r||regionAccess(r.name,save.maxStage)!=='open')return;if(current===i)return;current=i;chosen=null;mapTitle.textContent=r.name;help.textContent='임무 표식을 선택하면 정보를 확인할 수 있습니다';back.hidden=false;drawRegions();drawMarkers();animateView(zoomBounds(r));}
popup.addEventListener('cancel',e=>{e.preventDefault();popup.close();});popup.addEventListener('keydown',e=>{if(e.key==='Escape')e.stopPropagation();});popup.addEventListener('click',e=>{if(e.target!==popup)return;const box=popup.getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom)popup.close();});popup.addEventListener('close',()=>{const was=chosen;chosen=null;document.querySelectorAll('.marker').forEach(n=>n.setAttribute('aria-pressed','false'));if(was!==null)document.querySelectorAll('.marker')[was]?.focus();});function returnToWorld(){if(popup.open)popup.close();current=null;chosen=null;drawRegions();drawMarkers();showDirectory();animateView(original);}
back.addEventListener('click',returnToWorld);
document.querySelector('.map-wrap').addEventListener('click',event=>{if(current===null||popup.open||event.target.closest('.marker'))return;const matrix=svg.getScreenCTM();if(!matrix)return;const point=new DOMPoint(event.clientX,event.clientY).matrixTransform(matrix.inverse());if(!inside([point.x,point.y],data[current].polygon))returnToWorld();});window.addEventListener('pageshow',()=>{const next=loadSave();if(next.maxStage!==save.maxStage){save=next;if(current!==null&&regionAccess(data[current].name,save.maxStage)==='open')selectRegion(current);else{current=null;chosen=null;drawRegions();drawMarkers();showDirectory();setView(original);}}});window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!popup.open&&!e.defaultPrevented&&current!==null)back.click();});drawRegions();showDirectory();
